{
  "items": [
    {
      "name": "denomsClearable_zero",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {K : Type u_2} [inst : Semiring R] [inst_1 : CommSemiring K] {i : R →+* K} {b : R} {bi : K} (N : ℕ)\n  (a : R), bi * i b = 1 → DenomsClearable a b N 0 i"
    },
    {
      "name": "denomsClearable_of_natDegree_le",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {K : Type u_2} [inst : Semiring R] [inst_1 : CommSemiring K] {i : R →+* K} {b : R} {bi : K} (N : ℕ)\n  (a : R), bi * i b = 1 → ∀ (f : Polynomial R), f.natDegree ≤ N → DenomsClearable a b N f i"
    },
    {
      "name": "DenomsClearable",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {K : Type u_2} → [inst : Semiring R] → [inst_1 : CommSemiring K] → R → R → ℕ → Polynomial R → (R →+* K) → Prop"
    },
    {
      "name": "denomsClearable_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {K : Type u_2} [inst : Semiring R] [inst_1 : CommSemiring K] {b : R} {bi : K} (i : R →+* K)\n  (f : Polynomial R) (a : R), bi * i b = 1 → DenomsClearable a b f.natDegree f i"
    },
    {
      "name": "denomsClearable_C_mul_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {K : Type u_2} [inst : Semiring R] [inst_1 : CommSemiring K] {i : R →+* K} {b : R} {bi : K} {N : ℕ}\n  (a : R), bi * i b = 1 → ∀ {n : ℕ} (r : R), n ≤ N → DenomsClearable a b N (Polynomial.C r * Polynomial.X ^ n) i"
    },
    {
      "name": "MvPolynomial.eval₂Hom",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] → [inst_1 : CommSemiring S₁] → (R →+* S₁) → (σ → S₁) → MvPolynomial σ R →+* S₁"
    },
    {
      "name": "MvPolynomial.eval₂_eq_eval_map",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] (f : R →+* S₁)\n  (g : σ → S₁) (p : MvPolynomial σ R), MvPolynomial.eval₂ f g p = (MvPolynomial.eval g) ((MvPolynomial.map f) p)"
    },
    {
      "name": "MvPolynomial.aeval",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] →\n        [inst_1 : CommSemiring S₁] → [inst_2 : Algebra R S₁] → (σ → S₁) → MvPolynomial σ R →ₐ[R] S₁"
    },
    {
      "name": "MvPolynomial.eval₂_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] (g : R →+* S₁)\n  (X : σ → S₁) (f : MvPolynomial σ R),\n  MvPolynomial.eval₂ g X f = ∑ d ∈ f.support, g (MvPolynomial.coeff d f) * ∏ i ∈ d.support, X i ^ d i"
    },
    {
      "name": "MvPolynomial.eval₂",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] → [inst_1 : CommSemiring S₁] → (R →+* S₁) → (σ → S₁) → MvPolynomial σ R → S₁"
    }
  ]
}
